;(() => {
  if (typeof document !== 'undefined') {
    document.addEventListener('keydown', (e) => {
      if (e.code === undefined) {
        // Synthetic event (e.g., Chrome autofill). Ignore.
        return
      }

      pushToCurrentlyPressedKeys([mapCode(e.code)])
    })

    document.addEventListener('keyup', (e) => {
      if (e.code === undefined) {
        // Synthetic event (e.g., Chrome autofill). Ignore.
        return
      }

      removeFromCurrentlyPressedKeys([mapCode(e.code)])
    })
  }

  if (typeof window !== 'undefined') {
    window.addEventListener('blur', () => {
      currentlyPressedKeys.clear()
    })

    window.addEventListener('focus', () => {
      currentlyPressedKeys.clear()
    })

    window.addEventListener('contextmenu', () => {
      // Must clear pressed keys after existing `keydown` events in queue have resolved.
      setTimeout(() => {
        currentlyPressedKeys.clear()
      }, 0)
    })
  }

  if (typeof document !== 'undefined') {
    document.addEventListener('visibilitychange', () => {
      currentlyPressedKeys.clear()
    })
  }
})()

const currentlyPressedKeys: Set<string> = new Set<string>()

// https://github.com/microsoft/TypeScript/issues/17002
export function isReadonlyArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value)
}

/**
 * @guarantee ok.all-keys-pressed When several keys are given, `isHotkeyPressed` returns `true` only if all of them are pressed down, and `false` otherwise.
 * @guarantee ok.key-forms The `key` argument may be a single keycode such as "a", a delimited string such as "shift,a", or an array such as ["shift", "a"].
 * @guarantee ok.default-delimiter The `delimiter` used to split multiple keys from a single string is "," by default.
 */
export function isHotkeyPressed(key: string | readonly string[], delimiter = ','): boolean {
  const hotkeyArray = isReadonlyArray(key) ? key : key.split(delimiter)

  return hotkeyArray.every((hotkey) => currentlyPressedKeys.has(hotkey.trim().toLowerCase()))
}

export function pushToCurrentlyPressedKeys(key: string | string[]): void {
  const hotkeyArray = Array.isArray(key) ? key : [key]

  /*
  Due to a weird behavior on macOS we need to clear the set if the user pressed down the meta key and presses another key.
  https://stackoverflow.com/questions/11818637/why-does-javascript-drop-keyup-events-when-the-metakey-is-pressed-on-mac-browser
  Otherwise the set will hold all ever pressed keys while the meta key is down which leads to wrong results.
   */
  if (currentlyPressedKeys.has('meta')) {
    currentlyPressedKeys.forEach((key) => {
      if (!isHotkeyModifier(key)) {
        currentlyPressedKeys.delete(key.toLowerCase())
      }
    })
  }

  hotkeyArray.forEach((hotkey) => {
    currentlyPressedKeys.add(hotkey.toLowerCase())
  })
}

export function removeFromCurrentlyPressedKeys(key: string | string[]): void {
  const hotkeyArray = Array.isArray(key) ? key : [key]

  /*
  Due to a weird behavior on macOS we need to clear the set if the user pressed down the meta key and presses another key.
  https://stackoverflow.com/questions/11818637/why-does-javascript-drop-keyup-events-when-the-metakey-is-pressed-on-mac-browser
  Otherwise the set will hold all ever pressed keys while the meta key is down which leads to wrong results.
   */
  if (key === 'meta') {
    currentlyPressedKeys.clear()
  } else {
    hotkeyArray.forEach((hotkey) => {
      currentlyPressedKeys.delete(hotkey.toLowerCase())
    })
  }
}

