import type { HotkeyCallback, Keys, Options, OptionsOrDependencyArray } from './types'
import { type DependencyList, type RefCallback, useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react'
import { mapCode, parseHotkey, parseKeysHookInput, isHotkeyModifier } from './parseHotkeys'
import {
  isHotkeyEnabled,
  isHotkeyEnabledOnTag,
  isHotkeyMatchingKeyboardEvent,
  isKeyboardEventTriggeredByInput,
  isScopeActive,
  maybePreventDefault,
} from './validators'
import { useHotkeysContext } from './HotkeysProvider'
import { useBoundHotkeysProxy } from './BoundHotkeysProxyProvider'
import useDeepEqualMemo from './useDeepEqualMemo'
import { isReadonlyArray, pushToCurrentlyPressedKeys, removeFromCurrentlyPressedKeys } from './isHotkeyPressed'

const stopPropagation = (e: KeyboardEvent): void => {
  e.stopPropagation()
  e.preventDefault()
  e.stopImmediatePropagation()
}

const useSafeLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect

// Strip function properties from options so that inline callbacks don't trigger constant re-registration.
// Preserve boolean/undefined `enabled` so that toggling it dynamically re-runs the effect.
function getSerializableOptions(options?: Options): Omit<Options, 'preventDefault' | 'ignoreEventWhen'> | undefined {
  if (!options) return undefined
  const { enabled: _enabled, preventDefault: _preventDefault, ignoreEventWhen: _ignoreEventWhen, ...rest } = options

  if (typeof _enabled === 'function') {
    return rest
  }

  return { ...rest, enabled: _enabled }
}

/**
 * @guarantee ok.option-defaults The `options` defaults are `enabled` true, `enableOnFormTags` false, `enableOnContentEditable` false, `splitKey` "+", `delimiter` ",", `scopes` "*", `keydown` true, `preventDefault` false, `ignoreModifiers` false, `useKey` false, `sequenceTimeoutMs` 1000 and `sequenceSplitKey` ">".
 * @guarantee ok.keyup-only Setting `keyup` to `true` without setting `keydown` listens to `keyup` only; to listen to both, `keydown` and `keyup` must both be `true`.
 * @guarantee ok.delimiters With the default `delimiter` ",", the keys "ctrl+a, shift+b" listen for either combination, and with the default `splitKey` "+", "shift+a" fires when Shift and A are pressed together.
 * @guarantee ok.sequence-timeout With the keys "g>h>i" the user must press g, then h, then i in order, and the sequence resets if the next key is not pressed within `sequenceTimeoutMs`, which is 1000 milliseconds by default.
 * @guarantee ok.case-insensitive The `keys` argument is case-insensitive: "CTRL+S", "Ctrl+s" and "ctrl+S" all listen for the `ctrl` and `s` keys, and an uppercase letter is treated as lowercase.
 * @guarantee ok.modifiers The modifiers are "shift", "alt", "ctrl", "meta" and "mod", where "mod" triggers when either `ctrl` or `meta` is pressed, and "alt" and "option" are treated as identical.
 * @guarantee ok.enabled-modes When `enabled` is the boolean `false` the event listeners are removed, and when `enabled` is a function that returns `false` the listeners stay attached but the callback is skipped.
 * @guarantee ok.returns-ref It returns a React ref callback; when it is attached to an element, the hotkey fires only when that element or one of its children has focus.
 */
export default function useHotkeys<T extends HTMLElement>(
  keys: Keys,
  callback: HotkeyCallback,
  options?: OptionsOrDependencyArray,
  dependencies?: OptionsOrDependencyArray,
) {
  const [ref, _setRef] = useState<T | null>(null)
  const setRef = useCallback<RefCallback<T | null>>((instance) => {
    _setRef(instance)
    return () => _setRef(null)
  }, [])

  const hasTriggeredRef = useRef(false)

  const _options: Options | undefined = !Array.isArray(options)
    ? (options as Options)
    : !Array.isArray(dependencies)
      ? (dependencies as Options)
      : undefined
  const _keys: string = isReadonlyArray(keys) ? keys.join(_options?.delimiter) : keys
  const _deps: DependencyList | undefined = Array.isArray(options)
    ? options
    : Array.isArray(dependencies)
      ? dependencies
      : undefined

  // biome-ignore lint/correctness/useExhaustiveDependencies: is exhaustive
  const memoisedCB = useCallback(callback, _deps ?? [])
  const cbRef = useRef<HotkeyCallback>(memoisedCB)

  if (_deps) {
    cbRef.current = memoisedCB
  } else {
    cbRef.current = callback
  }

  const memoisedOptions = useDeepEqualMemo(getSerializableOptions(_options))

  // Keep function callbacks in refs so they're always up-to-date without causing effect re-registration.
  const enabledRef = useRef(_options?.enabled)
  enabledRef.current = _options?.enabled
  const preventDefaultRef = useRef(_options?.preventDefault)
  preventDefaultRef.current = _options?.preventDefault
  const ignoreEventWhenRef = useRef(_options?.ignoreEventWhen)
  ignoreEventWhenRef.current = _options?.ignoreEventWhen

  const { activeScopes } = useHotkeysContext()
  const proxy = useBoundHotkeysProxy()

  useSafeLayoutEffect(() => {
    if (enabledRef.current === false || !isScopeActive(activeScopes, memoisedOptions?.scopes)) {
      return
    }

    let recordedKeys: string[] = []
    let sequenceTimer: ReturnType<typeof setTimeout> | undefined

    const listener = (e: KeyboardEvent, isKeyUp = false) => {
      if (isKeyboardEventTriggeredByInput(e) && !isHotkeyEnabledOnTag(e, memoisedOptions?.enableOnFormTags)) {
        return
      }

      // TODO: SINCE THE EVENT IS NOW ATTACHED TO THE REF, THE ACTIVE ELEMENT CAN NEVER BE INSIDE THE REF. THE HOTKEY ONLY TRIGGERS IF THE
      // REF IS THE ACTIVE ELEMENT. THIS IS A PROBLEM SINCE FOCUSED SUB COMPONENTS WON'T TRIGGER THE HOTKEY.
      if (ref !== null) {
        const rootNode = ref.getRootNode()

        if (
          (rootNode instanceof Document || rootNode instanceof ShadowRoot) &&
          rootNode.activeElement !== ref &&
          !ref.contains(rootNode.activeElement)
        ) {
          stopPropagation(e)
          return
        }
      }

      if ((e.target as HTMLElement)?.isContentEditable && !memoisedOptions?.enableOnContentEditable) {
        return
      }

      parseKeysHookInput(_keys, memoisedOptions?.delimiter).forEach((key) => {
        if (key.includes(memoisedOptions?.splitKey ?? '+') && key.includes(memoisedOptions?.sequenceSplitKey ?? '>')) {
          console.warn(
            `Hotkey ${key} contains both ${memoisedOptions?.splitKey ?? '+'} and ${memoisedOptions?.sequenceSplitKey ?? '>'} which is not supported.`,
          )
          return
        }

        const hotkey = parseHotkey(
          key,
          memoisedOptions?.splitKey,
          memoisedOptions?.sequenceSplitKey,
          memoisedOptions?.useKey,
          memoisedOptions?.description,
          memoisedOptions?.metadata,
        )

        if (hotkey.isSequence) {
          // Set a timeout to check post which the sequence should reset
          sequenceTimer = setTimeout(() => {
            recordedKeys = []
          }, memoisedOptions?.sequenceTimeoutMs ?? 1000)

          const currentKey = hotkey.useKey ? e.key : mapCode(e.code)

          // TODO: Make modifiers work with sequences
          if (isHotkeyModifier(currentKey.toLowerCase())) {
            return
          }

          recordedKeys.push(currentKey)

          const expectedKey = hotkey.keys?.[recordedKeys.length - 1]
          if (currentKey !== expectedKey) {
            recordedKeys = []
            if (sequenceTimer) {
              clearTimeout(sequenceTimer)
            }
            return
          }

          // If the sequence is complete, trigger the callback
          if (recordedKeys.length === hotkey.keys?.length) {
            cbRef.current(e, hotkey)

            if (sequenceTimer) {
              clearTimeout(sequenceTimer)
            }

            recordedKeys = []
          }
        } else {
          if (
            isHotkeyMatchingKeyboardEvent(e, hotkey, memoisedOptions?.ignoreModifiers) ||
            hotkey.keys?.includes('*')
          ) {
            if (ignoreEventWhenRef.current?.(e)) {
              return
            }

            if (isKeyUp && hasTriggeredRef.current) {
              return
            }

            maybePreventDefault(e, hotkey, preventDefaultRef.current)

            if (!isHotkeyEnabled(e, hotkey, enabledRef.current)) {
              return
            }

            // Execute the user callback for that hotkey
            cbRef.current(e, hotkey)

            if (!isKeyUp) {
              hasTriggeredRef.current = true
            }
          }
        }
      })
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.code === undefined) {
        // Synthetic event (e.g., Chrome autofill).  Ignore.
        return
      }

      pushToCurrentlyPressedKeys(mapCode(event.code))

      if ((memoisedOptions?.keydown === undefined && memoisedOptions?.keyup !== true) || memoisedOptions?.keydown) {
        listener(event)
      }
    }

    const handleKeyUp = (event: KeyboardEvent) => {
      if (event.code === undefined) {
        // Synthetic event (e.g., Chrome autofill).  Ignore.
        return
      }

      removeFromCurrentlyPressedKeys(mapCode(event.code))

      hasTriggeredRef.current = false

      if (memoisedOptions?.keyup) {
        listener(event, true)
      }
    }

    const domNode = ref || _options?.document || document

    // @ts-expect-error TS2345
    domNode.addEventListener('keyup', handleKeyUp, _options?.eventListenerOptions)
    // @ts-expect-error TS2345
    domNode.addEventListener('keydown', handleKeyDown, _options?.eventListenerOptions)

    if (proxy) {
      parseKeysHookInput(_keys, memoisedOptions?.delimiter).forEach((key) => {
        proxy.addHotkey(
          parseHotkey(
            key,
            memoisedOptions?.splitKey,
            memoisedOptions?.sequenceSplitKey,
            memoisedOptions?.useKey,
            memoisedOptions?.description,
            memoisedOptions?.metadata,
          ),
        )
      })
    }

    return () => {
      // @ts-expect-error TS2345
      domNode.removeEventListener('keyup', handleKeyUp, _options?.eventListenerOptions)
      // @ts-expect-error TS2345
      domNode.removeEventListener('keydown', handleKeyDown, _options?.eventListenerOptions)

      if (proxy) {
        parseKeysHookInput(_keys, memoisedOptions?.delimiter).forEach((key) => {
          proxy.removeHotkey(
            parseHotkey(
              key,
              memoisedOptions?.splitKey,
              memoisedOptions?.sequenceSplitKey,
              memoisedOptions?.useKey,
              memoisedOptions?.description,
              memoisedOptions?.metadata,
            ),
          )
        })
      }

      recordedKeys = []
      if (sequenceTimer) {
        clearTimeout(sequenceTimer)
      }
    }
  }, [ref, memoisedOptions, activeScopes, _keys])

  return setRef
}

