import { useCallback, useMemo, useState, useEffect } from 'react'
import { mapCode } from './parseHotkeys'

/**
 * @guarantee ok.default-key-codes By default `useKey` is `false` and the hook records key codes, so pressing Shift+1 records "shift+1".
 * @guarantee ok.use-key-true With `useKey` set to `true` the hook records the produced character, so pressing Shift+1 on a US layout records "!".
 * @guarantee ok.blacklist The `blacklist` is empty by default, and keys named in it, such as "tab" and "enter", are not added to the recorded keys and keep their default behavior.
 * @guarantee ok.keys-is-set The first returned value is a `Set` of strings in which each recorded key appears only once.
 * @guarantee ok.controls The second returned value has `start`, `stop`, `resetKeys` and `isRecording`, where `isRecording` is `true` while recording is active and `false` otherwise.
 * @guarantee ok.reset-keys Calling `resetKeys` clears the recorded keys.
 */
export default function useRecordHotkeys(useKey = false, blacklist: string[] = []) {
  const [keys, setKeys] = useState(new Set<string>())
  const [isRecording, setIsRecording] = useState(false)

  const blacklistSet = useMemo(() => {
    return new Set(blacklist.map((k) => k.toLowerCase()))
  }, [blacklist])

  const handler = useCallback(
    (event: KeyboardEvent) => {
      if (event.code === undefined) {
        // Synthetic event (e.g., Chrome autofill). Ignore.
        return
      }

      const mappedKey = mapCode(useKey ? event.key : event.code).toLowerCase()

      // Do not interfere with keys present in the blacklist – allow them to work normally.
      if (blacklistSet.has(mappedKey)) {
        return
      }

      // Prevent the default behaviour for recorded keys so they don't interfere with the UI.
      event.preventDefault()
      event.stopPropagation()

      setKeys((prev) => {
        const newKeys = new Set(prev)

        newKeys.add(mappedKey)

        return newKeys
      })
    },
    [useKey, blacklistSet],
  )

  const stop = useCallback(() => {
    setIsRecording(false)
  }, [])

  const start = useCallback(() => {
    setKeys(new Set<string>())
    setIsRecording(true)
  }, [])

  const resetKeys = useCallback(() => {
    setKeys(new Set<string>())
  }, [])

  useEffect(() => {
    if (typeof document !== 'undefined' && isRecording) {
      document.addEventListener('keydown', handler)

      return () => {
        document.removeEventListener('keydown', handler)
      }
    }
  }, [isRecording, handler])

  return [keys, { start, stop, resetKeys, isRecording }] as const
}
